cat > /tmp/nd.js <<'EOF'
const fs=require('fs');
const f=process.argv[2];
const lines=fs.readFileSync(f,'latin1').split('\n');
if(lines[lines.length-1]==='')lines.pop();
for(const l of lines){ process.stdout.write(Buffer.from(l+'\n','latin1')); }
EOF
cd /workspace/dataset && ./test15_executable --a x --b x --c 1 --d 1 >/tmp/small.file 2>/dev/null; echo "small=$(wc -c </tmp/small.file) large=$(wc -c </tmp/full.file)"
node /tmp/nd.js /tmp/full.file | cmp - /tmp/full.file && echo "node repro stdout IDENTICAL (large)"
node /tmp/nd.js /tmp/small.file | cmp - /tmp/small.file && echo "node repro stdout IDENTICAL (small)"

cat > /tmp/nd2.js <<'EOF'
const fs=require('fs');
process.stdout.on('error',()=>{});
const lines=fs.readFileSync(process.argv[2],'latin1').split('\n');
if(lines[lines.length-1]==='')lines.pop();
for(const l of lines){ try{process.stdout.write(Buffer.from(l+'\n','latin1'));}catch(e){} }
EOF
cd /tmp
echo "--- nd2 small | true:"; node /tmp/nd2.js /tmp/small.file 2>/tmp/m1 | true; echo "rc=${PIPESTATUS[0]} err=$(wc -c </tmp/m1)"
echo "--- nd2 small >/dev/full:"; node /tmp/nd2.js /tmp/small.file >/dev/full 2>/tmp/m2; echo "rc=$? err=$(wc -c </tmp/m2)"
echo "--- nd2 small >&-:"; node /tmp/nd2.js /tmp/small.file >&- 2>/tmp/m3; echo "rc=$? err=$(wc -c </tmp/m3)"
echo "--- nd2 large | true:"; node /tmp/nd2.js /tmp/full.file 2>/tmp/m4 | true; echo "rc=${PIPESTATUS[0]} err=$(wc -c </tmp/m4)  [python gives 1 here]"
echo "--- nd2 normal correctness:"; node /tmp/nd2.js /tmp/full.file 2>/dev/null | cmp - /tmp/full.file && echo "large stdout OK rc-check"; node /tmp/nd2.js /tmp/small.file >/tmp/m5 2>/dev/null; echo "rc=$?"; cmp /tmp/m5 /tmp/small.file && echo "small stdout OK"
